def rubric_for(concept):
    from .course_catalog import topic
    if concept not in RUBRICS:raise ValueError('No independent reference rubric is available for this topic.')
    result=copy.deepcopy(RUBRICS[concept]);result['prerequisites']=topic(concept)['needs'];result['authorship']=AUTHORSHIP
    return result


def digest():return hashlib.sha256(json.dumps(RUBRICS,sort_keys=True,separators=(',',':')).encode()).hexdigest()


async def verify_oracle(concept,execution):
    from .video_curriculum import checked_run
    oracle=rubric_for(concept)['oracle']
    correct=await checked_run(execution,oracle['source'],None,[[]]);wrong=await checked_run(execution,oracle['mutant_source'],None,[[]])
    observed=correct['cases'][0];mutant=wrong['cases'][0]
    if observed.get('error') or observed.get('output','').strip()!=oracle['expected_output']:raise ValueError('The independent rubric oracle did not match its specified result.')
    if not mutant.get('error') and mutant.get('output','').strip()==oracle['expected_output']:raise ValueError('The independent common-error mutant was not distinguished.')
    return {'rubric_version':VERSION,'rubric_hash':digest(),'concept':concept,'oracle_passed':True,'mutant_rejected':True,'human_teacher_approved':False,'runtime':correct['runtime']}
